  }

  return (
    <div className="min-h-screen flex items-center justify-center pt-16 px-4">
      <div className="max-w-md w-full mx-auto p-8 rounded-lg">
        <div className="text-center mb-8">
            <h1 className="font-megrim text-5xl tracking-widest text-white mb-4 cursor-pointer" onClick={() => onNavigate('home')}>
                PASS
            </h1>
            <p className="text-gray-400">
                {isLogin ? 'Faça login na sua conta' : 'Crie uma nova conta'}
            </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
            {!isLogin && (
                <div>
                    <label htmlFor="name" className="text-sm font-medium text-gray-300 block mb-2 sr-only">Nome</label>
                    <input type="text" id="name" name="name" placeholder="Nome" required className="w-full p-3 bg-transparent border border-gray-700 rounded-md focus:ring-gray-500 focus:border-gray-500 placeholder-gray-500" />
                </div>
