                <input type="email" id="email" name="email" placeholder="Email" required className="w-full p-3 bg-transparent border border-gray-700 rounded-md focus:ring-gray-500 focus:border-gray-500 placeholder-gray-500" />
            </div>
            <div>
                <label htmlFor="password" className="text-sm font-medium text-gray-300 block mb-2 sr-only">Senha</label>
                <input type="password" id="password" name="password" placeholder="Senha" required className="w-full p-3 bg-transparent border border-gray-700 rounded-md focus:ring-gray-500 focus:border-gray-500 placeholder-gray-500" />
            </div>
            <button type="submit" className="w-full py-3 px-4 bg-white text-black font-semibold rounded-md hover:bg-gray-300 transition-colors duration-300">
                {isLogin ? 'Entrar' : 'Cadastrar'}
            </button>
        </form>

        <div className="text-center mt-6">
            <p className="text-sm text-gray-400">
                {isLogin ? "Não tem uma conta?" : "Já tem uma conta?"}
                <button onClick={() => setIsLogin(!isLogin)} className="font-medium text-white hover:underline ml-1">
                    {isLogin ? 'Cadastre-se' : 'Entrar'}
                </button>
            </p>
        </div>
      </div>
    </div>
  );
};

export default AuthPage;

