    switch(currentPage) {
      case 'product':
        return selectedProductInfo && (
          <ProductPage 
            product={selectedProductInfo.product}
            sectionProducts={selectedProductInfo.sectionProducts}
            onNavigateBack={() => handleNavigate('home')}
            isLoggedIn={isLoggedIn}
