                products={passSportsProducts} 
                variant="passSports" 
                onProductSelect={(product) => handleProductSelect(product, passSportsProducts)}
              />
            </main>
            <Footer />
          </>
        );
    }
  };

  return (
    <div className="bg-black text-white min-h-screen">
